class Solution:
    def minThreshold(self, nums: List[int], k: int) -> int:
        import bisect
        n = len(nums)
        sv = sorted(set(nums))
        m = len(sv)
        bit = [0] * (m + 1)
        def add(p):
            p += 1
            while p <= m:
                bit[p] += 1
                p += p & (-p)
        def qry(p):
            s = 0; p += 1
            while p > 0:
                s += bit[p]; p -= p & (-p)
            return s
        def count(x):
            for i in range(m + 1):
                bit[i] = 0
            total = 0
            for v in nums:
                hi = bisect.bisect_right(sv, v + x)
                lo = bisect.bisect_right(sv, v)
                total += qry(hi - 1) - qry(lo - 1)
                add(bisect.bisect_left(sv, v))
            return total
        lo, hi = 0, max(nums) - min(nums)
        if count(hi) < k:
            return -1
        while lo < hi:
            mid = (lo + hi) // 2
            if count(mid) >= k:
                hi = mid
            else:
                lo = mid + 1
        return lo

