class Solution {
public:
    int minThreshold(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> sv = nums;
        sort(sv.begin(), sv.end()); sv.erase(unique(sv.begin(), sv.end()), sv.end());
        int m = sv.size();
        vector<int> bit(m + 1, 0);
        auto add = [&](int p) { for (++p; p <= m; p += p & -p) bit[p]++; };
        auto qry = [&](int p) { int s = 0; for (++p; p > 0; p -= p & -p) s += bit[p]; return s; };
        auto count = [&](long long x) {
            fill(bit.begin(), bit.end(), 0);
            long long total = 0;
            for (int v : nums) {
                int hi = upper_bound(sv.begin(), sv.end(), (long long)v + x) - sv.begin();
                int lo = upper_bound(sv.begin(), sv.end(), v) - sv.begin();
                total += qry(hi - 1) - qry(lo - 1);
                add(lower_bound(sv.begin(), sv.end(), v) - sv.begin());
            }
            return total;
        };
        long long lo = 0, hi = (long long)*max_element(nums.begin(), nums.end()) - *min_element(nums.begin(), nums.end());
        if (count(hi) < k) return -1;
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (count(mid) >= k) hi = mid; else lo = mid + 1;
        }
        return (int) lo;
    }
};

