class Solution {
    public int minThreshold(int[] nums, int k) {
        int n = nums.length;
        int[] sv = nums.clone();
        Arrays.sort(sv);
        int m = 0;
        for (int i = 0; i < n; i++) if (i == 0 || sv[i] != sv[i-1]) sv[m++] = sv[i];
        int[] bit = new int[m + 1];
        java.util.function.IntUnaryOperator add = p -> { for (++p; p <= m; p += p & (-p)) bit[p]++; return 0; };
        java.util.function.IntUnaryOperator qry = p -> { int s = 0; for (++p; p > 0; p -= p & (-p)) s += bit[p]; return s; };
        java.util.function.LongPredicate count = x -> {
            Arrays.fill(bit, 0);
            long total = 0;
            for (int v : nums) {
                int hi = upperBound(sv, m, v + x), lo = upperBound(sv, m, v);
                total += qry.applyAsInt(hi - 1) - qry.applyAsInt(lo - 1);
                add.applyAsInt(lowerBound(sv, m, v));
            }
            return total >= k;
        };
        long lo = 0, hi = (long) Integer.MAX_VALUE;
        for (int v : nums) { hi = Math.max(hi, 0); }
        long mx = 0, mn = Long.MAX_VALUE;
        for (int v : nums) { mx = Math.max(mx, v); mn = Math.min(mn, v); }
        hi = mx - mn;
        if (!count.test(hi)) return -1;
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (count.test(mid)) hi = mid; else lo = mid + 1;
        }
        return (int) lo;
    }
    private int lowerBound(int[] a, int len, long key) { int lo = 0, hi = len; while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] < key) lo = mid + 1; else hi = mid; } return lo; }
    private int upperBound(int[] a, int len, long key) { int lo = 0, hi = len; while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] <= key) lo = mid + 1; else hi = mid; } return lo; }
}

