var minThreshold = function(nums, k) {
    const n = nums.length;
    const sv = [...new Set(nums)].sort((a, b) => a - b);
    const m = sv.length;
    const bit = new Array(m + 1).fill(0);
    const add = p => { for (++p; p <= m; p += p & (-p)) bit[p]++; };
    const qry = p => { let s = 0; for (++p; p > 0; p -= p & (-p)) s += bit[p]; return s; };
    const ub = key => { let lo = 0, hi = m; while (lo < hi) { const mid = (lo + hi) >> 1; if (sv[mid] <= key) lo = mid + 1; else hi = mid; } return lo; };
    const lb = key => { let lo = 0, hi = m; while (lo < hi) { const mid = (lo + hi) >> 1; if (sv[mid] < key) lo = mid + 1; else hi = mid; } return lo; };
    const count = x => {
        bit.fill(0);
        let total = 0;
        for (const v of nums) {
            total += qry(ub(v + x) - 1) - qry(ub(v) - 1);
            add(lb(v));
        }
        return total;
    };
    let lo = 0, hi = Math.max(...nums) - Math.min(...nums);
    if (count(hi) < k) return -1;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (count(mid) >= k) hi = mid; else lo = mid + 1;
    }
    return lo;
};
